t.script:
(function () {
  function $(id){ return document.getElementById(id); }
  function on(el, ev, cb){ if (el) el.addEventListener(ev, cb); }
  function whenLoaded(img){
    return new Promise(resolve=>{
      if (!img) return resolve();
      if (img.complete && img.naturalWidth) return resolve();
      img.addEventListener('load', ()=>resolve(), {once:true});
    });
  }

  async function buildCanvas() {
    const stage = $('spw_canvas');
    const base  = $('spw_product_img');
    const logo  = $('spw_logo_preview');
    if (!stage || !base) return null;

    await whenLoaded(base);
    if (logo && !logo.classList.contains('d-none') && logo.src) {
      await whenLoaded(logo);
    }

    const dpr = window.devicePixelRatio || 1;
    const stageRect = stage.getBoundingClientRect();
    const baseRect  = base.getBoundingClientRect();

    const canvas = document.createElement('canvas');
    canvas.width  = Math.max(1, Math.round(stageRect.width * dpr));
    canvas.height = Math.max(1, Math.round(stageRect.height * dpr));
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, stageRect.width, stageRect.height);

    const bx = baseRect.left - stageRect.left;
    const by = baseRect.top  - stageRect.top;
    ctx.drawImage(base, bx, by, baseRect.width, baseRect.height);

    if (logo && !logo.classList.contains('d-none') && logo.src) {
      const lr = logo.getBoundingClientRect();
      const cx = (lr.left - stageRect.left) + lr.width/2;
      const cy = (lr.top  - stageRect.top ) + lr.height/2;
      const deg = parseFloat(($('spw_rotation') && $('spw_rotation').value) || 0);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(deg * Math.PI / 180);
      ctx.drawImage(logo, -lr.width/2, -lr.height/2, lr.width, lr.height);
      ctx.restore();
    }
    return canvas;
  }

  window.spwReset = function () {
    const logo = $('spw_logo_preview');
    if (logo) { logo.classList.add('d-none'); logo.removeAttribute('src'); }
    const s = $('spw_size');      if (s) s.value = 100;
    const x = $('spw_pos_x');     if (x) x.value = 0;
    const y = $('spw_pos_y');     if (y) y.value = 10;
    const r = $('spw_rotation');  if (r) r.value = 0;
  };

  async function downloadPNG() {
    try {
      const canvas = await buildCanvas();
      if (!canvas) return alert('No se pudo preparar la imagen.');

      // iOS safe: toBlob + ObjectURL
      if (canvas.toBlob) {
        canvas.toBlob(function(blob){
          if (!blob) { alert('No se pudo generar el PNG.'); return; }
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = 'personalizacion.png';
          document.body.appendChild(a);
          a.click();
          setTimeout(()=>{ URL.revokeObjectURL(url); a.remove(); }, 0);
        }, 'image/png');
      } else {
        const url = canvas.toDataURL('image/png');
        const a = document.createElement('a');
        a.href = url;
        a.download = 'personalizacion.png';
        document.body.appendChild(a);
        a.click();
        a.remove();
      }
    } catch (e) {
      console.error('Descargar PNG', e);
      alert('No se pudo generar el PNG.');
    }
  }

  function pick(name, obj, fallback){
    return (obj && typeof obj[name] === 'string') ? obj[name] : fallback;
  }

  async function addToCart() {
    try {
      const variantId = parseInt((($('spw_variant_id')||{}).value)||'0', 10);
      const qty       = Math.max(1, parseInt((($('spw_qty')||{}).value)||'1', 10));
      if (!variantId) { alert('Variante no válida.'); return; }

      const canvas = await buildCanvas();
      if (!canvas) { alert('No se pudo preparar la imagen.'); return; }
      const dataUrl = canvas.toDataURL('image/png');
      const png_b64 = (dataUrl.split(',')[1]||'');

      const techEl = document.querySelector('input[name="spw_tech"]:checked');
      const svgEl  = document.querySelector('input[name="spw_svg_color"]:checked');

      const payload = {
        variant_id: variantId,
        qty: qty,
        tech: techEl ? techEl.value : '',
        svg_color: svgEl ? svgEl.value : '',
        notes: (($('spw_notes')||{}).value)||'',
        png_b64: png_b64,
      };

      const resp = await fetch('/spw/add_to_cart', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Requested-With': 'XMLHttpRequest'
        },
        body: JSON.stringify(payload),
        credentials: 'same-origin',
      });

      const text = await resp.text();
      let data = null;
      try { data = JSON.parse(text); } catch(_) {}

      if (resp.ok && data && data.ok) {
        window.location.assign(data.cart_url || '/shop/cart');
        return;
      }

      // Mostrar mensaje útil
      let msg =
        pick('message', data, '') ||
        (data && data.error && (data.error.data && data.error.data.message)) ||
        text || 'No se pudo añadir al carrito.';
      alert(typeof msg === 'string' ? msg : 'No se pudo añadir al carrito.');
      console.error('add_to_cart response', resp.status, data || text);

    } catch (e) {
      console.error('Añadir carrito', e);
      alert('No se pudo añadir al carrito.');
    }
  }

  function init(){
    on($('spw_download_png_btn'), 'click', downloadPNG);
    on($('spw_add_to_cart_btn'), 'click', addToCart);
    on($('spw_reset_btn'), 'click', function(e){ e.preventDefault(); window.spwReset(); });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
